import re

HEADLINES = ['Lahore mein shadeed barish, schools band', 'Karachi traffic: barish ke baad sarkein band', 'PSL final Lahore mein hoga', 'Islamabad weather: aaj barish ka imkaan']

def build_index(docs):
    my_index = {}
    for i in range(len(docs)):
        text = docs[i].lower()
        words = re.findall(r"[a-z0-9]+", text)
        unique_words = []
        for word in words:
            if word not in unique_words:
                unique_words.append(word)
        for word in unique_words:
            if word not in my_index:
                my_index[word] = []
            my_index[word].append(i)
    for word in my_index:
        my_index[word].sort()
    return my_index

def search_and(index, a, b):
    if a not in index or b not in index:
        return []
    list_a = index[a]
    list_b = index[b]
    result = []
    for id1 in list_a:
        for id2 in list_b:
            if id1 == id2:
                result.append(id1)
    return result

print(build_index(HEADLINES)['barish'])

